COMMENT ON COLUMN request_to_pay.responded_at IS 'Payer response time';
COMMENT ON COLUMN request_to_pay.custom_field_1 IS 'Tenant-defined custom field 1; label, type and validation configured in custom_field_definition';
COMMENT ON COLUMN request_to_pay.custom_field_2 IS 'Tenant-defined custom field 2; label, type and validation configured in custom_field_definition';
COMMENT ON COLUMN request_to_pay.custom_field_3 IS 'Tenant-defined custom field 3; label, type and validation configured in custom_field_definition';
COMMENT ON COLUMN request_to_pay.custom_field_4 IS 'Tenant-defined custom field 4; label, type and validation configured in custom_field_definition';
COMMENT ON COLUMN request_to_pay.custom_field_5 IS 'Tenant-defined custom field 5; label, type and validation configured in custom_field_definition';
CREATE INDEX ix_request_to_pay_tenant ON request_to_pay (tenant_id, created_at);
CREATE INDEX ix_request_to_pay_requester_customer_id ON request_to_pay (requester_customer_id);
CREATE INDEX ix_request_to_pay_requester_account_id ON request_to_pay (requester_account_id);
CREATE INDEX ix_request_to_pay_requester_wallet_id ON request_to_pay (requester_wallet_id);
CREATE INDEX ix_request_to_pay_payer_customer_id ON request_to_pay (payer_customer_id);
CREATE INDEX ix_request_to_pay_paid_payment_id ON request_to_pay (paid_payment_id);
ALTER TABLE request_to_pay ENABLE ROW LEVEL SECURITY;
CREATE POLICY tenant_isolation ON request_to_pay USING (tenant_id = current_setting('app.tenant_id')::uuid);
CREATE TRIGGER trg_request_to_pay_touch BEFORE UPDATE ON request_to_pay FOR EACH ROW EXECUTE FUNCTION touch_row();

-- payment: A payment instruction in the ISO 20022 canonical model (pain.001 / pacs.008 aligned)
CREATE TABLE payment (
  id                           uuid PRIMARY KEY DEFAULT uuidv7(),
  tenant_id                    uuid NOT NULL,
  created_at                   timestamptz NOT NULL DEFAULT now(),
  created_by                   varchar(64),
  updated_at                   timestamptz NOT NULL DEFAULT now(),
  updated_by                   varchar(64),
  row_version                  integer NOT NULL DEFAULT 1,
  payment_type                 varchar(40) NOT NULL CHECK (payment_type IN ('INTERNAL_TRANSFER', 'P2P', 'DOMESTIC', 'INSTANT', 'CROSS_BORDER', 'BULK_ITEM', 'PAYROLL', 'DIRECT_DEBIT', 'REQUEST_TO_PAY', 'BILL_PAYMENT', 'QR_PAYMENT', 'LINK_PAYMENT', 'REFUND', 'RETURN')),
  direction                    varchar(40) NOT NULL CHECK (direction IN ('OUTBOUND', 'INBOUND', 'INTERNAL')),
  status                       varchar(40) NOT NULL DEFAULT 'INITIATED' CHECK (status IN ('INITIATED', 'SCREENING', 'PENDING_APPROVAL', 'APPROVED', 'SUBMITTED', 'ACCEPTED', 'SETTLED', 'REJECTED', 'RETURNED', 'FAILED', 'CANCELLED', 'IN_REPAIR', 'ON_HOLD')),
  channel                      varchar(40) NOT NULL CHECK (channel IN ('API', 'MOBILE', 'WEB', 'BRANCH', 'USSD', 'AGENT', 'BULK_FILE', 'OPEN_BANKING', 'SCHEDULER', 'INBOUND_RAIL')),
  priority                     varchar(40) NOT NULL DEFAULT 'NORMAL' CHECK (priority IN ('NORMAL', 'HIGH', 'URGENT')),
  idempotency_key              varchar(128) NOT NULL,
  customer_id                  uuid,
  debtor_account_id            uuid,
  debtor_wallet_id             uuid,
  debtor_ledger_account_id     uuid,
  debtor_name                  varchar(140),
  debtor_account_id_type       varchar(40) CHECK (debtor_account_id_type IN ('IBAN', 'BBAN', 'ACCOUNT_NUMBER', 'WALLET', 'PROXY', 'CARD_PAN_TOKEN', 'INTERNAL')),
  debtor_account_number        varchar(64),
  debtor_agent_bic             varchar(11),
  debtor_agent_clearing_id     varchar(35),
  debtor_country               char(2),
  payee_id                     uuid REFERENCES payee(id),
  creditor_name                varchar(140),
  creditor_account_id_type     varchar(40) CHECK (creditor_account_id_type IN ('IBAN', 'BBAN', 'ACCOUNT_NUMBER', 'WALLET', 'PROXY', 'CARD_PAN_TOKEN', 'INTERNAL')),
  creditor_account_number      varchar(64),
  creditor_agent_bic           varchar(11),
  creditor_agent_clearing_id   varchar(35),
  creditor_country             char(2),
  creditor_address             jsonb,
  creditor_account_id          uuid,
  creditor_wallet_id           uuid,
  creditor_merchant_id         uuid,
  amount                       numeric(28,8) NOT NULL,
  currency                     char(3) NOT NULL,
  instructed_amount            numeric(28,8),
  instructed_currency          char(3),
  settlement_amount            numeric(28,8),
  settlement_currency          char(3),
  fx_quote_id                  uuid,
  fx_rate                      numeric(18,10),
  fee_amount                   numeric(28,8),
  fee_currency                 char(3),
  tax_amount                   numeric(28,8),
  tax_breakdown                jsonb,
  charge_bearer                varchar(40) NOT NULL DEFAULT 'SHAR' CHECK (charge_bearer IN ('DEBT', 'CRED', 'SHAR', 'SLEV')),
  end_to_end_id                varchar(35) NOT NULL,
  uetr                         uuid,
  instruction_id               varchar(35),
  transaction_id               varchar(35),
  clearing_system_ref          varchar(64),
  purpose_code                 varchar(4),
  category_purpose             varchar(4),
  remittance_unstructured      varchar(140),
  remittance_structured        jsonb,
  reference                    varchar(35),
  requested_execution_date     date,
  value_date                   date,
  rail_id                      uuid,
  rail_code                    varchar(32),
  hold_id                      uuid,
  journal_entry_id             uuid,
  screening_result_id          uuid,
  limit_check_id               uuid,
  fraud_score                  numeric(18,10),
  fraud_score_id               uuid,
  fraud_decision               varchar(40) CHECK (fraud_decision IN ('ALLOW', 'STEP_UP', 'REVIEW', 'BLOCK')),
  fraud_alert_id               uuid,
  fraud_degraded               boolean NOT NULL DEFAULT false,
  fraud_rescore_attempts       integer NOT NULL DEFAULT 0,
  fraud_next_rescore_at        timestamptz,
  upstream_fraud_score_id      uuid,
  hold_reason                  varchar(32),
  risk_context                 jsonb,
  rejection_code               varchar(8),
  rejection_reason             varchar(255),
  bulk_payment_id              uuid REFERENCES bulk_payment(id),
  mandate_id                   uuid REFERENCES payment_mandate(id),
  request_to_pay_id            uuid REFERENCES request_to_pay(id),
  original_payment_id          uuid REFERENCES payment(id),
  ob_consent_id                uuid,
  initiated_by                 varchar(64),
  submitted_at                 timestamptz,
  accepted_at                  timestamptz,
  settled_at                   timestamptz,
  metadata                     jsonb,
  custom_field_1               varchar(500),
  custom_field_2               varchar(500),
  custom_field_3               varchar(500),
  custom_field_4               varchar(500),
  custom_field_5               varchar(500),
  CONSTRAINT uq_payment_1 UNIQUE (tenant_id, idempotency_key)
);
COMMENT ON TABLE payment IS 'A payment instruction in the ISO 20022 canonical model (pain.001 / pacs.008 aligned)';
COMMENT ON COLUMN payment.id IS 'Unique id (UUIDv7, time-ordered)';
COMMENT ON COLUMN payment.tenant_id IS 'Owning tenant; enforced by row-level security';
COMMENT ON COLUMN payment.created_at IS 'Creation time';
COMMENT ON COLUMN payment.created_by IS 'Principal that created the row';
COMMENT ON COLUMN payment.updated_at IS 'Last update time';
COMMENT ON COLUMN payment.updated_by IS 'Principal that last updated the row';
COMMENT ON COLUMN payment.row_version IS 'Optimistic lock version; send as If-Match';
COMMENT ON COLUMN payment.payment_type IS 'Business type of payment';
COMMENT ON COLUMN payment.direction IS 'Outbound, inbound or internal (book transfer)';
COMMENT ON COLUMN payment.status IS 'Lifecycle status';
COMMENT ON COLUMN payment.channel IS 'Channel that initiated the payment';
COMMENT ON COLUMN payment.priority IS 'Requested priority';
COMMENT ON COLUMN payment.idempotency_key IS 'Client key; a replay returns the original payment';
COMMENT ON COLUMN payment.customer_id IS 'Initiating or receiving customer';
COMMENT ON COLUMN payment.debtor_account_id IS 'Internal source account (outbound / internal)';
COMMENT ON COLUMN payment.debtor_wallet_id IS 'Internal source wallet';
COMMENT ON COLUMN payment.debtor_ledger_account_id IS 'Ledger account debited (resolved from the debtor account)';
COMMENT ON COLUMN payment.debtor_name IS 'Debtor (payer) name [PII]';
COMMENT ON COLUMN payment.debtor_account_id_type IS 'Scheme of debtor account identifier';
COMMENT ON COLUMN payment.debtor_account_number IS 'Debtor IBAN / account number / wallet id [PII]';
COMMENT ON COLUMN payment.debtor_agent_bic IS 'Debtor agent BIC';
COMMENT ON COLUMN payment.debtor_agent_clearing_id IS 'Debtor agent clearing id (sort code, ABA, IFSC)';
COMMENT ON COLUMN payment.debtor_country IS 'Debtor country';
COMMENT ON COLUMN payment.payee_id IS 'Saved payee used, if any';
COMMENT ON COLUMN payment.creditor_name IS 'Creditor (payee) name (required unless payee_id or creditor_account_id is given) [PII]';
COMMENT ON COLUMN payment.creditor_account_id_type IS 'Scheme of creditor account identifier (required with creditor_account_number)';
COMMENT ON COLUMN payment.creditor_account_number IS 'Creditor IBAN / account number / wallet id / proxy [PII]';
COMMENT ON COLUMN payment.creditor_agent_bic IS 'Creditor agent BIC';
COMMENT ON COLUMN payment.creditor_agent_clearing_id IS 'Creditor agent clearing id (sort code, ABA, IFSC)';
COMMENT ON COLUMN payment.creditor_country IS 'Creditor country';
COMMENT ON COLUMN payment.creditor_address IS 'Structured postal address (ISO 20022 PostalAddress24) [PII]';
COMMENT ON COLUMN payment.creditor_account_id IS 'Internal destination account (inbound / internal)';
COMMENT ON COLUMN payment.creditor_wallet_id IS 'Internal destination wallet';
COMMENT ON COLUMN payment.creditor_merchant_id IS 'Merchant paid (QR, link payments)';
COMMENT ON COLUMN payment.amount IS 'Amount debited from the debtor in currency';
COMMENT ON COLUMN payment.currency IS 'Debit currency';
COMMENT ON COLUMN payment.instructed_amount IS 'Amount instructed to arrive (cross-border)';
COMMENT ON COLUMN payment.instructed_currency IS 'Currency of the instructed amount';
COMMENT ON COLUMN payment.settlement_amount IS 'Interbank settlement amount';
COMMENT ON COLUMN payment.settlement_currency IS 'Interbank settlement currency';
COMMENT ON COLUMN payment.fx_quote_id IS 'FX quote accepted for this payment';
COMMENT ON COLUMN payment.fx_rate IS 'Applied FX rate';
COMMENT ON COLUMN payment.fee_amount IS 'Fee charged to the debtor';
COMMENT ON COLUMN payment.fee_currency IS 'Fee currency';
COMMENT ON COLUMN payment.tax_amount IS 'Transaction taxes debited on top of the amount and fee (e.g. Colombia GMF 4x1000, IVA on the fee), in the payment currency';
COMMENT ON COLUMN payment.tax_breakdown IS 'Taxes applied: {total, lines: [{tax_type, name, rate, base, exempt_amount, amount, reason}]}';
COMMENT ON COLUMN payment.charge_bearer IS 'Who bears charges (ISO 20022 ChrgBr)';
COMMENT ON COLUMN payment.end_to_end_id IS 'ISO 20022 end-to-end id (server-generated; shown to the creditor)';
COMMENT ON COLUMN payment.uetr IS 'SWIFT gpi unique end-to-end transaction reference (server-generated UUIDv4)';
COMMENT ON COLUMN payment.instruction_id IS 'Instruction id between instructing parties (server-generated)';
COMMENT ON COLUMN payment.transaction_id IS 'Interbank transaction id assigned on submission';
COMMENT ON COLUMN payment.clearing_system_ref IS 'Reference returned by the clearing system';
COMMENT ON COLUMN payment.purpose_code IS 'ISO 20022 external purpose code';
COMMENT ON COLUMN payment.category_purpose IS 'ISO 20022 category purpose (e.g. SALA, SUPP)';
COMMENT ON COLUMN payment.remittance_unstructured IS 'Unstructured remittance information';
COMMENT ON COLUMN payment.remittance_structured IS 'Structured remittance (creditor reference, invoices)';
COMMENT ON COLUMN payment.reference IS 'Payer reference shown on statements';
COMMENT ON COLUMN payment.requested_execution_date IS 'Requested execution date (future-dated payments)';
COMMENT ON COLUMN payment.value_date IS 'Interbank value date';
COMMENT ON COLUMN payment.rail_id IS 'Rail chosen by routing';
COMMENT ON COLUMN payment.rail_code IS 'Rail code at submission time';
COMMENT ON COLUMN payment.hold_id IS 'Ledger hold placed on the debtor account';
COMMENT ON COLUMN payment.journal_entry_id IS 'Ledger posting on settlement';
COMMENT ON COLUMN payment.screening_result_id IS 'Sanctions screening result';
COMMENT ON COLUMN payment.limit_check_id IS 'Limits reservation (committed on settlement, released on failure)';
COMMENT ON COLUMN payment.fraud_score IS 'Fraud score 0..1 (fraud-service score / 1000) before release';
COMMENT ON COLUMN payment.fraud_score_id IS 'fraud-service evaluation of this payment (idempotency key pay-fraud:<payment id>)';
COMMENT ON COLUMN payment.fraud_decision IS 'Fraud decision applied: fraud-service''s, or the fail-open / fail-closed fallback when scoring was unavailable';
COMMENT ON COLUMN payment.fraud_alert_id IS 'Fraud alert whose resolution releases or rejects a payment held for review';
COMMENT ON COLUMN payment.fraud_degraded IS 'Fraud scoring timed out or was unavailable; the configured fallback decided';
COMMENT ON COLUMN payment.fraud_rescore_attempts IS 'Automatic re-scoring attempts of a payment held because fraud scoring was unavailable';
COMMENT ON COLUMN payment.fraud_next_rescore_at IS 'Next automatic re-scoring of a degraded fraud hold (exponential backoff; empty = none scheduled)';
COMMENT ON COLUMN payment.upstream_fraud_score_id IS 'Evaluation of the originating service (wallet-service payout) reused instead of scoring again: a recent ALLOW of the same customer, amount and currency, accepted only from an allow-listed service over an internal token';
COMMENT ON COLUMN payment.hold_reason IS 'Why the payment is ON_HOLD (FRAUD_REVIEW)';
COMMENT ON COLUMN payment.risk_context IS 'Session context for fraud scoring, set server-side by the channel (device_fingerprint, ip_address, ip_country, session_id, user_agent) [PII]';
COMMENT ON COLUMN payment.rejection_code IS 'ISO 20022 status reason code';
COMMENT ON COLUMN payment.rejection_reason IS 'Human-readable rejection reason';
COMMENT ON COLUMN payment.bulk_payment_id IS 'Parent bulk payment';
COMMENT ON COLUMN payment.mandate_id IS 'Mandate used (direct debits)';
COMMENT ON COLUMN payment.request_to_pay_id IS 'Request-to-pay being paid';
COMMENT ON COLUMN payment.original_payment_id IS 'Original payment for returns and refunds';
COMMENT ON COLUMN payment.ob_consent_id IS 'Open banking consent (PIS)';
COMMENT ON COLUMN payment.initiated_by IS 'Principal that initiated the payment';
COMMENT ON COLUMN payment.submitted_at IS 'Time submitted to the rail';
COMMENT ON COLUMN payment.accepted_at IS 'Time accepted by the rail / creditor agent';
COMMENT ON COLUMN payment.settled_at IS 'Time settled';
COMMENT ON COLUMN payment.metadata IS 'Client-defined key/value metadata';
COMMENT ON COLUMN payment.custom_field_1 IS 'Tenant-defined custom field 1; label, type and validation configured in custom_field_definition';
COMMENT ON COLUMN payment.custom_field_2 IS 'Tenant-defined custom field 2; label, type and validation configured in custom_field_definition';
COMMENT ON COLUMN payment.custom_field_3 IS 'Tenant-defined custom field 3; label, type and validation configured in custom_field_definition';
COMMENT ON COLUMN payment.custom_field_4 IS 'Tenant-defined custom field 4; label, type and validation configured in custom_field_definition';
COMMENT ON COLUMN payment.custom_field_5 IS 'Tenant-defined custom field 5; label, type and validation configured in custom_field_definition';
CREATE INDEX ix_payment_tenant ON payment (tenant_id, created_at);
