CREATE TRIGGER trg_payment_touch BEFORE UPDATE ON payment FOR EACH ROW EXECUTE FUNCTION touch_row();

-- payment_status_history: Every status transition of a payment, with the rail or user that caused it. Append-only.
CREATE TABLE payment_status_history (
  id                           uuid PRIMARY KEY DEFAULT uuidv7(),
  tenant_id                    uuid NOT NULL,
  created_at                   timestamptz NOT NULL DEFAULT now(),
  created_by                   varchar(64),
  payment_id                   uuid NOT NULL REFERENCES payment(id),
  from_status                  varchar(40) CHECK (from_status IN ('INITIATED', 'SCREENING', 'PENDING_APPROVAL', 'APPROVED', 'SUBMITTED', 'ACCEPTED', 'SETTLED', 'REJECTED', 'RETURNED', 'FAILED', 'CANCELLED', 'IN_REPAIR', 'ON_HOLD')),
  to_status                    varchar(40) NOT NULL CHECK (to_status IN ('INITIATED', 'SCREENING', 'PENDING_APPROVAL', 'APPROVED', 'SUBMITTED', 'ACCEPTED', 'SETTLED', 'REJECTED', 'RETURNED', 'FAILED', 'CANCELLED', 'IN_REPAIR', 'ON_HOLD')),
  reason_code                  varchar(8),
  reason                       varchar(255),
  actor                        varchar(64),
  rail_message_id              uuid,
  custom_field_1               varchar(500),
  custom_field_2               varchar(500),
  custom_field_3               varchar(500),
  custom_field_4               varchar(500),
  custom_field_5               varchar(500)
);
COMMENT ON TABLE payment_status_history IS 'Every status transition of a payment, with the rail or user that caused it. Append-only.';
COMMENT ON COLUMN payment_status_history.id IS 'Unique id (UUIDv7, time-ordered)';
COMMENT ON COLUMN payment_status_history.tenant_id IS 'Owning tenant; enforced by row-level security';
COMMENT ON COLUMN payment_status_history.created_at IS 'Creation time';
COMMENT ON COLUMN payment_status_history.created_by IS 'Principal that created the row';
COMMENT ON COLUMN payment_status_history.payment_id IS 'Payment';
COMMENT ON COLUMN payment_status_history.from_status IS 'Previous status';
COMMENT ON COLUMN payment_status_history.to_status IS 'New status';
COMMENT ON COLUMN payment_status_history.reason_code IS 'ISO 20022 reason code';
COMMENT ON COLUMN payment_status_history.reason IS 'Reason text';
COMMENT ON COLUMN payment_status_history.actor IS 'User, service or rail that caused the change';
COMMENT ON COLUMN payment_status_history.rail_message_id IS 'Rail message that triggered the change';
COMMENT ON COLUMN payment_status_history.custom_field_1 IS 'Tenant-defined custom field 1; label, type and validation configured in custom_field_definition';
COMMENT ON COLUMN payment_status_history.custom_field_2 IS 'Tenant-defined custom field 2; label, type and validation configured in custom_field_definition';
COMMENT ON COLUMN payment_status_history.custom_field_3 IS 'Tenant-defined custom field 3; label, type and validation configured in custom_field_definition';
COMMENT ON COLUMN payment_status_history.custom_field_4 IS 'Tenant-defined custom field 4; label, type and validation configured in custom_field_definition';
COMMENT ON COLUMN payment_status_history.custom_field_5 IS 'Tenant-defined custom field 5; label, type and validation configured in custom_field_definition';
CREATE INDEX ix_payment_status_history_tenant ON payment_status_history (tenant_id, created_at);
CREATE INDEX ix_payment_status_history_payment_id ON payment_status_history (payment_id);
CREATE INDEX ix_payment_status_history_rail_message_id ON payment_status_history (rail_message_id);
ALTER TABLE payment_status_history ENABLE ROW LEVEL SECURITY;
CREATE POLICY tenant_isolation ON payment_status_history USING (tenant_id = current_setting('app.tenant_id')::uuid);
CREATE TRIGGER trg_payment_status_history_append_only BEFORE UPDATE OR DELETE ON payment_status_history FOR EACH ROW EXECUTE FUNCTION forbid_mutation();

-- payment_return: Return of a settled payment (pacs.004), inbound or outbound
CREATE TABLE payment_return (
  id                           uuid PRIMARY KEY DEFAULT uuidv7(),
  tenant_id                    uuid NOT NULL,
  created_at                   timestamptz NOT NULL DEFAULT now(),
  created_by                   varchar(64),
  updated_at                   timestamptz NOT NULL DEFAULT now(),
  updated_by                   varchar(64),
  row_version                  integer NOT NULL DEFAULT 1,
  payment_id                   uuid NOT NULL REFERENCES payment(id),
  return_payment_id            uuid REFERENCES payment(id),
  direction                    varchar(40) NOT NULL CHECK (direction IN ('OUTBOUND', 'INBOUND', 'INTERNAL')),
  status                       varchar(40) NOT NULL DEFAULT 'INITIATED' CHECK (status IN ('INITIATED', 'SUBMITTED', 'COMPLETED', 'REJECTED', 'FAILED')),
  reason_code                  varchar(8) NOT NULL,
  reason                       varchar(255),
  amount                       numeric(28,8) NOT NULL,
  currency                     char(3) NOT NULL,
  fee_amount                   numeric(28,8) NOT NULL DEFAULT 0,
  return_id                    varchar(35),
  journal_entry_id             uuid,
  completed_at                 timestamptz,
  custom_field_1               varchar(500),
  custom_field_2               varchar(500),
  custom_field_3               varchar(500),
  custom_field_4               varchar(500),
  custom_field_5               varchar(500)
);
COMMENT ON TABLE payment_return IS 'Return of a settled payment (pacs.004), inbound or outbound';
COMMENT ON COLUMN payment_return.id IS 'Unique id (UUIDv7, time-ordered)';
COMMENT ON COLUMN payment_return.tenant_id IS 'Owning tenant; enforced by row-level security';
COMMENT ON COLUMN payment_return.created_at IS 'Creation time';
COMMENT ON COLUMN payment_return.created_by IS 'Principal that created the row';
COMMENT ON COLUMN payment_return.updated_at IS 'Last update time';
COMMENT ON COLUMN payment_return.updated_by IS 'Principal that last updated the row';
COMMENT ON COLUMN payment_return.row_version IS 'Optimistic lock version; send as If-Match';
COMMENT ON COLUMN payment_return.payment_id IS 'Original payment';
COMMENT ON COLUMN payment_return.return_payment_id IS 'Payment created to move the funds back';
COMMENT ON COLUMN payment_return.direction IS 'Whether we return or receive a return';
COMMENT ON COLUMN payment_return.status IS 'Status';
COMMENT ON COLUMN payment_return.reason_code IS 'ISO 20022 return reason (e.g. AC04, MD07)';
COMMENT ON COLUMN payment_return.reason IS 'Additional information';
COMMENT ON COLUMN payment_return.amount IS 'Returned amount';
COMMENT ON COLUMN payment_return.currency IS 'Currency';
COMMENT ON COLUMN payment_return.fee_amount IS 'Return fee deducted';
COMMENT ON COLUMN payment_return.return_id IS 'Return identification on the rail';
COMMENT ON COLUMN payment_return.journal_entry_id IS 'Ledger posting moving the funds back';
COMMENT ON COLUMN payment_return.completed_at IS 'Completion time';
COMMENT ON COLUMN payment_return.custom_field_1 IS 'Tenant-defined custom field 1; label, type and validation configured in custom_field_definition';
COMMENT ON COLUMN payment_return.custom_field_2 IS 'Tenant-defined custom field 2; label, type and validation configured in custom_field_definition';
COMMENT ON COLUMN payment_return.custom_field_3 IS 'Tenant-defined custom field 3; label, type and validation configured in custom_field_definition';
COMMENT ON COLUMN payment_return.custom_field_4 IS 'Tenant-defined custom field 4; label, type and validation configured in custom_field_definition';
COMMENT ON COLUMN payment_return.custom_field_5 IS 'Tenant-defined custom field 5; label, type and validation configured in custom_field_definition';
CREATE INDEX ix_payment_return_tenant ON payment_return (tenant_id, created_at);
CREATE INDEX ix_payment_return_payment_id ON payment_return (payment_id);
CREATE INDEX ix_payment_return_return_payment_id ON payment_return (return_payment_id);
CREATE INDEX ix_payment_return_journal_entry_id ON payment_return (journal_entry_id);
