-- payment_recall: Request to recall a payment (camt.056) and its resolution (camt.029)
CREATE TABLE payment_recall (
  id                           uuid PRIMARY KEY DEFAULT uuidv7(),
  tenant_id                    uuid NOT NULL,
  created_at                   timestamptz NOT NULL DEFAULT now(),
  created_by                   varchar(64),
  updated_at                   timestamptz NOT NULL DEFAULT now(),
  updated_by                   varchar(64),
  row_version                  integer NOT NULL DEFAULT 1,
  payment_id                   uuid NOT NULL REFERENCES payment(id),
  direction                    varchar(40) NOT NULL CHECK (direction IN ('OUTBOUND', 'INBOUND', 'INTERNAL')),
  status                       varchar(40) NOT NULL DEFAULT 'REQUESTED' CHECK (status IN ('REQUESTED', 'PENDING', 'ACCEPTED', 'REJECTED', 'CANCELLED')),
  reason_code                  varchar(8) NOT NULL,
  reason                       varchar(255),
  requested_by                 varchar(64),
  response_code                varchar(8),
  response_reason              varchar(255),
  return_id                    uuid REFERENCES payment_return(id),
  resolved_at                  timestamptz,
  custom_field_1               varchar(500),
  custom_field_2               varchar(500),
  custom_field_3               varchar(500),
  custom_field_4               varchar(500),
  custom_field_5               varchar(500)
);
