COMMENT ON COLUMN payment_recall.updated_at IS 'Last update time';
COMMENT ON COLUMN payment_recall.updated_by IS 'Principal that last updated the row';
COMMENT ON COLUMN payment_recall.row_version IS 'Optimistic lock version; send as If-Match';
COMMENT ON COLUMN payment_recall.payment_id IS 'Payment to recall';
COMMENT ON COLUMN payment_recall.direction IS 'Recall we send or receive';
COMMENT ON COLUMN payment_recall.status IS 'Status';
COMMENT ON COLUMN payment_recall.reason_code IS 'Recall reason (DUPL, FRAD, TECH, CUST)';
COMMENT ON COLUMN payment_recall.reason IS 'Additional information';
COMMENT ON COLUMN payment_recall.requested_by IS 'Requester';
COMMENT ON COLUMN payment_recall.response_code IS 'Response reason code';
COMMENT ON COLUMN payment_recall.response_reason IS 'Response text';
COMMENT ON COLUMN payment_recall.return_id IS 'Resulting return';
COMMENT ON COLUMN payment_recall.resolved_at IS 'Resolution time';
COMMENT ON COLUMN payment_recall.custom_field_1 IS 'Tenant-defined custom field 1; label, type and validation configured in custom_field_definition';
COMMENT ON COLUMN payment_recall.custom_field_2 IS 'Tenant-defined custom field 2; label, type and validation configured in custom_field_definition';
COMMENT ON COLUMN payment_recall.custom_field_3 IS 'Tenant-defined custom field 3; label, type and validation configured in custom_field_definition';
COMMENT ON COLUMN payment_recall.custom_field_4 IS 'Tenant-defined custom field 4; label, type and validation configured in custom_field_definition';
COMMENT ON COLUMN payment_recall.custom_field_5 IS 'Tenant-defined custom field 5; label, type and validation configured in custom_field_definition';
